import java.util.*;
import java.io.*;

public class Main {
    static long[] deleteInRange(long[] values, long lo, long hi) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] values = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            values[i] = (long) in.nval;
        }
        in.nextToken();
        long lo = (long) in.nval;
        in.nextToken();
        long hi = (long) in.nval;
        long[] res = deleteInRange(values, lo, hi);
        StringBuilder sb = new StringBuilder();
        sb.append(res.length).append("\n");
        if (res.length > 0) {
            for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
